{
  "name": "MaineCare Medicare Savings Programs",
  "eligibility": {
    "age": null,
    "income_limits": {
      "summary": "Eligibility is based on Medicare status and countable monthly income. Maine’s current MSP rules appear to use three tiers—QMB, SLMB, and QI—with income levels higher than older federal minimums. The official Maine page says people with higher income levels now qualify and points applicants to apply rather than self-screen first.[1]",
      "tiers": [
        {
          "tier": "QMB",
          "income_limit": "The official Maine materials indicate QMB is the most generous tier and pays Part B premiums plus Medicare deductibles and coinsurance; a recent Maine document shows QMB at 140% FPL with an asset limit, while another 2026 Maine source says QMB is now at 185% FPL and monthly income for a single person is $2,461 / couple $3,337.[5][8][12][15]",
          "notes": "Because the sources conflict on exact thresholds, families should verify the current limit on the Maine DHHS page or by applying; Maine explicitly says not to rule yourself out before applying.[1][5][8][12][15]"
        },
        {
          "tier": "SLMB",
          "income_limit": "Recent Maine sources identify SLMB as paying the Medicare Part B premium and show it between QMB and QI in income eligibility; older and newer materials conflict on whether the threshold is 160% FPL, 170% FPL, or another adjusted figure.[8][9][13][14][15]",
          "notes": "Exact current dollar limits were not consistently stated across the sources surfaced; Maine’s own page directs applicants to apply for a determination rather than self-assess.[1][5][8][12][15]"
        },
        {
          "tier": "QI",
          "income_limit": "Recent sources show QI as the least generous tier and paying the Part B premium only; one Maine source states QI at 185% FPL, while another 2026 source shows a higher upper band up to 250% FPL with a single-person monthly income limit of $3,325 and couple limit of $4,509.[8][12][15]",
          "notes": "QI can be subject to annual funding/availability rules in some states, but Maine materials found here emphasize applying through MaineCare rather than a separate waitlist description.[1][8][12][15]"
        }
      ],
      "full_picture": "MaineCare MSP eligibility depends on Medicare enrollment, income, and in some older guidance, assets. Maine’s current public-facing materials indicate the program expanded in July 2024 and now covers people with higher income levels than before.[1][8][12][15]"
    },
    "asset_limits": {
      "summary": "Older Maine guidance lists an asset limit of $50,000 per individual or $75,000 per couple for MSP, with only liquid assets counting.[5][9][14] A 2026 Maine Council on Aging summary says there is no asset test for MSP, which conflicts with the Maine DHHS guideline documents.[12]",
      "what_counts": [
        "Liquid assets in older guidance[5][9][14]"
      ],
      "what_is_exempt": [
        "The surfaced official snippets did not list the full exemption set; older materials specifically say only liquid assets count, implying non-liquid assets may be exempt.[5][9][14]"
      ],
      "important_caveat": "Because the sources conflict on whether any asset test applies, the safest family strategy is to apply and let Maine determine countable resources.[1][5][12][14]"
    },
    "other_requirements": [
      "The person must have Medicare, and Maine materials state eligibility is for people who have Medicare and may qualify for Part A and/or Part B premium help.[1][10][12]",
      "Must be a Maine resident and apply through Maine DHHS / MaineCare channels.[1][2][4]",
      "Some tiers in older guidance required entitlement to both Medicare Part A and Part B.[5][9][14]"
    ]
  },
  "benefits": {
    "type": "financial",
    "value": "Depending on the tier, MaineCare may pay the Medicare Part B premium only (SLMB/QI) or the Part B premium plus Medicare deductibles and coinsurance (QMB); Maine also states MSP can help pay Part A premiums in some cases.[1][5][10][12][15]",
    "varies_by": "priority_tier"
  },
  "application": {
    "methods": [
      "Online: MyMaineConnection.gov[1][12]",
      "Maine DHHS Applications & Forms page for downloadable application options[2]",
      "Mail, email, or fax after completing the paper application[12]",
      "In-person / other DHHS options referenced on the MaineCare options page[4]"
    ],
    "processing_time": "No official processing-time number was surfaced in the available sources. Maine’s public materials emphasize applying rather than self-screening, but do not provide a specific turnaround time in the excerpts found.[1][4][12]",
    "waitlist": null,
    "forms": [
      "MaineCare application used for MaineCare programs including Medicare Savings Program (Buy-In)[2]",
      "Paper MaineCare application downloadable from the DHHS Applications & Forms page[2][12]"
    ],
    "documents": [
      "Proof of Medicare enrollment (Part A and/or Part B as relevant)[1][5][9][10][12][14]",
      "Income documents such as Social Security award letters, pension statements, pay stubs, or retirement account statements",
      "Resource/asset information if asked, especially bank statements and information about liquid assets[5][9][14]",
      "Identification and Maine residency information",
      "Any current Medicare card or insurance notices"
    ]
  },
  "geography": {
    "statewide": true,
    "restrictions": "No county restriction surfaced; the program is statewide for eligible Maine residents.[1][4][12]",
    "regional_variations": "No regional benefit variation was surfaced. The main practical variation is administrative rather than substantive: application channels are statewide, and the sources found do not describe region-specific MSP offices or different benefit levels by county.[1][4][12]",
    "offices_or_providers": []
  },
  "official_source": "https://www.maine.gov/dhhs/oms/mainecare-options/older-adults-and-adults-with-disabilities",
  "gotchas": [
    "Maine’s MSP rules appear to have changed in 2024, so older income tables may be outdated; families should use current Maine DHHS guidance rather than old handouts.[1][5][8][15]",
    "The sources conflict on asset limits: some official-style Maine documents show a liquid-asset test, while another 2026 summary says there is no asset test.[5][9][12][14]",
    "Income thresholds also conflict across materials; some sources still show older 140%/160%/170%/185% FPL figures, while newer material indicates higher eligibility levels after July 1, 2024.[1][5][8][12][15]",
    "Applicants should not assume they are over-income because Maine explicitly says people with higher income levels now qualify and advises applying anyway.[1]",
    "QI and related MSP tiers can be subtle because the benefit may only cover the Part B premium, while QMB can also cover deductibles and coinsurance.[1][5][10][12][15]",
    "The program name can be confusing: MaineCare uses 'Medicare Savings Program' and 'Buy-In' language in its application materials.[2]"
  ],
  "data_shape_notes": "This program’s data structure is tiered, income-driven, and partially affected by conflicting published thresholds; benefits scale by MSP tier (QMB/SLMB/QI), not by household size alone. The key nuance is that Maine expanded MSP eligibility in 2024, so older tables may understate who qualifies.[1][5][8][12][15]"
}
